  _push(`<div${ssrRenderAttrs(_attrs)}><div style="${ssrRenderStyle({ "display": "none" })}" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /tutorials/agentic-todo-machine.md for this page in Markdown format</div><h1 id="build-an-agentic-todo-machine" tabindex="-1">Build an Agentic Todo Machine <a class="header-anchor" href="#build-an-agentic-todo-machine" aria-label="Permalink to “Build an Agentic Todo Machine”">​</a></h1>`);
